 function summaryByDistrict(rows,allRows){const result=new Map();for(const d of S.hierarchy?.districts||[])result.set(d.id,{rows:[],bestTier:null,review:0});for(const a of rows)for(const id of areaDistricts(a)){const item=result.get(id);if(!item)continue;item.rows.push(a);if(a.eligible&&a.demand===true&&tierClass(a.qualifyingTier))item.bestTier=item.bestTier===null?a.qualifyingTier:Math.min(item.bestTier,a.qualifyingTier);}for(const a of allRows)if(a.reviewCandidate||a.demand===null)for(const id of areaDistricts(a)){const item=result.get(id);if(item)item.review++;}return result;}
 function accessibleLayer(layer,label,action){layer.unbindTooltip?.();layer.on('click',action);layer.on('add',()=>{const element=layer.getElement?.();if(element){element.removeAttribute?.('aria-hidden');element.setAttribute('tabindex','0');element.setAttribute('role','button');element.setAttribute('aria-label',layer.yolkAccessibleLabel||label);if(S.keyboardElements.has(element))return;S.keyboardElements.add(element);element.addEventListener('keydown',event=>{if(['Enter',' '].includes(event.key)){event.preventDefault();action();}});}});}
